/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeWoodstockState(
  dst: WoodstockState,
  src: WoodstockState,
): void {
  if (!dst.taskQueue && src.taskQueue) {
    dst.taskQueue = src.taskQueue;
  } else if (dst.taskQueue && src.taskQueue) {
    mergeTaskItem(dst.taskQueue, src.taskQueue);
  }
  if (!dst.eventStream && src.eventStream) {
    dst.eventStream = src.eventStream;
  } else if (dst.eventStream && src.eventStream) {
    mergeEventData(dst.eventStream, src.eventStream);
  }
  if (!dst.status && src.status) {
    dst.status = src.status;
  } else if (dst.status && src.status) {
    mergeServiceStatus(dst.status, src.status);
  }
}
